import { expect, test, type Page } from "@playwright/test";
import { boot, cashierSql } from "./harness";

/**
 * `Alt`+digit must navigate and nothing else.
 *
 * Windows reads a held Alt plus digits as a legacy **Alt code** and, on Alt
 * release, hands the window a `WM_CHAR` of its own — `Alt`+`1` types ☺. That
 * character is not part of the keydown the shortcut swallows, so it arrives at
 * the page as a separate text insertion. This suite cannot reproduce the *OS*
 * half (the Alt code is generated by user32 on Windows; this box is Linux), but
 * it can reproduce the half that matters for the app: an insertion landing in a
 * focused field right after the shortcut fired. `keyboard.insertText` goes
 * through the same Chromium editing path a `WM_CHAR` does, so the guard is
 * exercised exactly where it has to hold.
 *
 * The control case is load-bearing: without it, a guard that simply ate every
 * keystroke would pass the first two tests.
 *
 * Note which keys are used. `Alt`+`1` is a real shortcut (Pos → Restock) and so
 * a navigation; `Alt`+`7` maps to nothing, so the field keeps the focus the
 * character has to be refused in.
 */
const seed = [cashierSql("Raisya", "123456")];

async function openToko(page: Page) {
  const errors = await boot(page, { sql: seed });

  await page.getByRole("button", { name: /Raisya/ }).click();
  await page.getByLabel(/kata sandi/i).fill("123456");
  await page.getByRole("button", { name: /masuk/i }).click();
  await expect(page.getByRole("heading", { name: "Beranda", level: 1 })).toBeVisible();

  await page.getByRole("button", { name: "Toko", exact: true }).click();
  await expect(page).toHaveURL(/#\/pos/);

  return errors;
}

/** The goods search bar, which is the field a cashier's cursor is usually in. */
function search(page: Page) {
  return page.getByPlaceholder(/Cari barang untuk dijual/i);
}

test("Alt+digit still navigates", async ({ page }) => {
  await openToko(page);

  await search(page).focus();
  await page.keyboard.press("Alt+1");

  await expect(page).toHaveURL(/#\/restock/);
});

test("the character Windows flushes back is swallowed", async ({ page }) => {
  await openToko(page);

  await search(page).focus();
  // A digit with no shortcut behind it: the page stays put, so whatever the
  // insertion does to the focused field is visible.
  await page.keyboard.press("Alt+7");
  // What user32 sends on Alt release, in the same editing path Chromium uses.
  await page.keyboard.insertText("☺");

  await expect(search(page)).toHaveValue("");
});

test("typing is untouched when no Alt+digit came first", async ({ page }) => {
  await openToko(page);

  await search(page).focus();
  await page.keyboard.insertText("☺");

  await expect(search(page)).toHaveValue("☺");
});
